import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {useState} from 'react'
import {Button, Label, Link, Truncate} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import type {NetworkSettingsResult} from '../types/payloads'

interface NetworkSettingsResultsTableProps {
  results: NetworkSettingsResult[]
}

export function NetworkSettingsResultsTable({results}: NetworkSettingsResultsTableProps) {
  return (
    <Table.Container>
      <DataTable
        data={results}
        columns={[
          {
            header: 'ID',
            field: 'id',
            renderCell: row => <ResourceIdCell value={row.id} />,
          },
          {
            header: 'Name',
            field: 'displayName',
            renderCell: row => row.displayName || row.resourceName,
          },
          {
            header: 'Business ID',
            field: 'businessId',
            renderCell: row =>
              row.businessId ? (
                <Link href={`/stafftools/search?query=${encodeURIComponent(row.businessId)}`}>{row.businessId}</Link>
              ) : (
                '-'
              ),
          },

          {
            header: 'Location',
            field: 'location',
          },
          {
            header: 'Resource ID',
            field: 'resourceId',
            renderCell: row => <ResourceIdCell value={row.resourceId} />,
          },
          {
            header: 'Virtual Network',
            field: 'virtualNetwork',
          },
          {
            header: 'Subnet',
            field: 'subnet',
          },
          {
            header: 'Subnet ID',
            field: 'subnetId',
            renderCell: row => <ResourceIdCell value={row.subnetId} />,
          },
          {
            header: 'State',
            field: 'state',
            renderCell: row => <StateLabel state={row.state} />,
          },
          {
            header: 'Config ID',
            field: 'networkConfigurationId',
            renderCell: row => <ResourceIdCell value={row.networkConfigurationId} />,
          },
        ]}
      />
    </Table.Container>
  )
}

function ResourceIdCell({value}: {value: string}) {
  const [isExpanded, setIsExpanded] = useState(false)

  return (
    <span className="d-inline-flex flex-items-start gap-1">
      <Button
        size="small"
        variant="invisible"
        onClick={() => setIsExpanded(current => !current)}
        aria-expanded={isExpanded}
        aria-label={isExpanded ? 'Collapse full resource ID' : 'Expand full resource ID'}
      >
        {isExpanded ? (
          <span>{value}</span>
        ) : (
          <Truncate title={value} inline>
            {value}
          </Truncate>
        )}
      </Button>
      <CopyToClipboardButton
        size="small"
        textToCopy={value}
        ariaLabel="Copy full resource ID"
        tooltipProps={{direction: 's'}}
      />
    </span>
  )
}

function StateLabel({state}: {state: string}) {
  const variant = state === 'Succeeded' ? 'success' : state === 'Failed' ? 'danger' : 'accent'
  return <Label variant={variant}>{state}</Label>
}
