import {useState, useCallback} from 'react'
import {TextInput, Button, Spinner, Flash, UnderlineNav, PageHeader} from '@primer/react'
import styles from './SearchPage.module.css'
import {SearchIcon} from '@primer/octicons-react'
import type {SearchPagePayload, NetworkSettingsResult, SubnetResult} from '../types/payloads'
import {Constants} from '../helpers/constants'
import {searchNetworkSettings, searchSubnets} from '../services/network-settings-search'
import {NetworkSettingsResultsTable} from '../components/NetworkSettingsResultsTable'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {networkSettingsSearchRoute} from './network-settings-search-route'
import {SubnetResultsTable} from '../components/SubnetResultsTable'
import {ScopedCommands} from '@github-ui/ui-commands'

type SearchTab = 'settings' | 'subnets'

export function SearchPageEntrypointFuture() {
  const {data: payload} = useRouteQuery(networkSettingsSearchRoute, 'mainQuery')
  return <SearchPage payload={payload} />
}

function SearchPage({payload}: {payload: SearchPagePayload}) {
  const [activeTab, setActiveTab] = useState<SearchTab>('settings')
  const [settingsQuery, setSettingsQuery] = useState(payload.searchQuery)
  const [subnetQuery, setSubnetQuery] = useState('')
  const [results, setResults] = useState<NetworkSettingsResult[]>(payload.searchResults)
  const [subnetResults, setSubnetResults] = useState<SubnetResult[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [hasSearched, setHasSearched] = useState(false)

  const isSettingsTab = activeTab === 'settings'
  const searchQuery = isSettingsTab ? settingsQuery : subnetQuery
  const setSearchQuery = isSettingsTab ? setSettingsQuery : setSubnetQuery

  const handleSearch = useCallback(async () => {
    const trimmedQuery = searchQuery.trim()
    if (!trimmedQuery) return

    setIsLoading(true)
    setError(null)
    setHasSearched(true)

    if (activeTab === 'settings') {
      const response = await searchNetworkSettings(trimmedQuery)
      if (response.error) {
        setError(response.error)
        setResults([])
      } else {
        setResults(response.results ?? [])
      }
    } else {
      const response = await searchSubnets(trimmedQuery)
      if (response.error) {
        setError(response.error)
        setSubnetResults([])
      } else {
        setSubnetResults(response.results ?? [])
      }
    }

    setIsLoading(false)
  }, [searchQuery, activeTab])

  const handleTabChange = useCallback(
    (tab: SearchTab) => {
      if (tab === activeTab) return
      setActiveTab(tab)
      setError(null)
      setHasSearched(false)
    },
    [activeTab],
  )

  const placeholder = isSettingsTab ? Constants.searchPlaceholder : Constants.subnetSearchPlaceholder
  const buttonLabel = isSettingsTab ? Constants.searchButtonLabel : Constants.subnetSearchButtonLabel
  const emptyMessage = isSettingsTab ? Constants.emptyStateMessage : Constants.subnetEmptyStateMessage
  const noResultsMessage = isSettingsTab ? Constants.noResultsMessage : Constants.noSubnetResultsMessage
  /**
   * Selects the appropriate result set based on the currently active tab.
   *
   * In short, a *setting* represents a top-level network configuration entity,
   * while a *subnet* is a more specific entity that may be part of a network setting.
   */
  const currentResults = isSettingsTab ? results : subnetResults

  return (
    <div>
      <PageHeader hasBorder className={styles.PageHeader}>
        {Constants.stafftoolPageTitle}
      </PageHeader>

      <UnderlineNav aria-label="Search type">
        <UnderlineNav.Item
          aria-current={activeTab === 'settings' ? 'page' : undefined}
          href="#settings"
          onSelect={event => {
            event.preventDefault()
            handleTabChange('settings')
          }}
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        >
          Network Settings
        </UnderlineNav.Item>
        <UnderlineNav.Item
          aria-current={activeTab === 'subnets' ? 'page' : undefined}
          href="#subnets"
          onSelect={event => {
            event.preventDefault()
            handleTabChange('subnets')
          }}
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        >
          Subnet Info (SAL)
        </UnderlineNav.Item>
      </UnderlineNav>

      <ScopedCommands commands={{'github:select': handleSearch}}>
        <div className={styles.searchBar}>
          <div className={styles.searchInput}>
            <TextInput
              aria-label={placeholder}
              placeholder={placeholder}
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              leadingVisual={SearchIcon}
              block
            />
          </div>
          <Button
            variant="primary"
            onClick={handleSearch}
            disabled={isLoading || !searchQuery.trim()}
            aria-label={buttonLabel}
            aria-busy={isLoading}
          >
            {isLoading ? <Spinner size="small" /> : buttonLabel}
          </Button>
        </div>
      </ScopedCommands>

      {error && (
        <div className={styles.flashContainer}>
          <Flash variant="danger">{error}</Flash>
        </div>
      )}

      {hasSearched && !isLoading && !error && currentResults.length === 0 && (
        <div className={styles.flashContainer}>
          <Flash>{noResultsMessage}</Flash>
        </div>
      )}

      {!hasSearched && currentResults.length === 0 && <div className={styles.emptyState}>{emptyMessage}</div>}

      {isSettingsTab && results.length > 0 && <NetworkSettingsResultsTable results={results} />}
      {!isSettingsTab && subnetResults.length > 0 && <SubnetResultsTable results={subnetResults} />}
    </div>
  )
}
