import type {SubnetResult} from '../types/payloads'
import styles from './SubnetResultsTable.module.css'

interface SubnetResultsTableProps {
  results: SubnetResult[]
}

export function SubnetResultsTable({results}: SubnetResultsTableProps) {
  if (results.length === 0) return null

  // Extract column headers from the first result's keys
  const columns = Object.keys(results[0] ?? {}).filter(key => key !== 'index')

  return (
    <table className={styles.table}>
      <thead>
        <tr className={styles.headerRow}>
          {columns.map(col => (
            <th key={col} className={styles.headerCell}>
              {col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {results.map((result, idx) => (
          <tr key={idx} className={styles.dataRow}>
            {columns.map(col => (
              <td key={col} className={styles.dataCell}>
                <CellValue value={result[col]} />
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}

// This component handles rendering of cell values, including pretty-printing JSON objects
function CellValue({value}: {value: unknown}) {
  if (value == null) return null
  if (typeof value === 'object') {
    return <pre className={styles.jsonPre}>{JSON.stringify(value, null, 2)}</pre>
  }
  if (typeof value === 'string') {
    const parsed = tryParseJson(value)
    if (parsed !== undefined) {
      return <pre className={styles.jsonPre}>{JSON.stringify(parsed, null, 2)}</pre>
    }
  }
  return <>{String(value)}</>
}

// Utility function to attempt parsing a string as JSON, returning undefined if it fails
function tryParseJson(value: string): object | undefined {
  try {
    const parsed: unknown = JSON.parse(value)
    if (typeof parsed === 'object' && parsed !== null) {
      return parsed
    }
  } catch {
    // not JSON
  }
  return undefined
}
